package com.honorablemobile
import org.junit.Assert.*
import org.junit.Test
import kotlin.random.Random
class VideoBilingualCaptionsTest {
 private fun srt(cues:List<VideoCaption>)=cues.mapIndexed{i,c->"${i+1}\n${VideoCaptions.formatTime(c.startMs)} --> ${VideoCaptions.formatTime(c.endMs)}\n${c.text}"}.joinToString("\n\n")
 private fun clip(cues:List<VideoCaption>)=VideoSegment(0,5000,captions=cues,captionSourceUri="content://synthetic/primary-subtitles")
 private fun merge(a:List<VideoCaption>,b:List<VideoCaption>)=VideoBilingualCaptions.prepare(listOf(clip(a)),0,10000,srt(b))
 @Test fun partialOverlapAndSingleTrackGapsKeepExactTextsAndUnionBoundaries(){val a=listOf(VideoCaption(0,1000,"A"),VideoCaption(2000,3000,"B"));val b=listOf(VideoCaption(500,2500,"α"));val r=merge(a,b);assertEquals(listOf(VideoCaption(0,500,"A"),VideoCaption(500,1000,"A\nα"),VideoCaption(1000,2000,"α"),VideoCaption(2000,2500,"B\nα"),VideoCaption(2500,3000,"B")),r.clips[0].captions);assertEquals(2,r.primaryCount);assertEquals(1,r.secondaryCount);assertEquals(5,r.outputCount);assertEquals(1000L,r.overlapSourceMs)}
 @Test fun touchingAndEmptyGapsNeverInventSharedTextOrHoldCaptions(){val r=merge(listOf(VideoCaption(0,1000,"A")),listOf(VideoCaption(1000,2000,"B"),VideoCaption(3000,4000,"C")));assertEquals(listOf(VideoCaption(0,1000,"A"),VideoCaption(1000,2000,"B"),VideoCaption(3000,4000,"C")),r.clips[0].captions);assertEquals(0L,r.overlapSourceMs)}
 @Test fun adjacentEqualCombinedTextIsCoalescedWithoutRemovingItsWords(){val r=merge(listOf(VideoCaption(0,2000,"A")),listOf(VideoCaption(500,1000,"X"),VideoCaption(1000,1500,"X")));assertEquals(listOf(VideoCaption(0,500,"A"),VideoCaption(500,1500,"A\nX"),VideoCaption(1500,2000,"A")),r.clips[0].captions);assertEquals(1000L,r.overlapSourceMs)}
 @Test fun identicalWordsAcrossLanguagesAreNotSilentlyDeduplicated(){val cue=VideoCaption(0,1000,"Same");assertEquals("Same\nSame",merge(listOf(cue),listOf(cue)).clips[0].captions.single().text)}
 @Test fun unicodeAndValidThreeLineStackKeepExactPrimaryAboveSecondary(){val r=merge(listOf(VideoCaption(0,1000,"日本語\nSecond line")),listOf(VideoCaption(0,1000,"العربية 😀")));assertEquals("日本語\nSecond line\nالعربية 😀",r.clips[0].captions.single().text)}
 @Test fun combinedLineAndCharacterOverflowAreRefusedInsteadOfDroppingText(){for((a,b)in listOf("A\nB" to "C\nD","x".repeat(200) to "y".repeat(100))){assertThrows(IllegalArgumentException::class.java){merge(listOf(VideoCaption(0,1000,a)),listOf(VideoCaption(0,1000,b)))}}}
 @Test fun invalidSrtOverlapsOutsideSourceUnicodeAndTransferBoundsFail(){val c=listOf(clip(listOf(VideoCaption(0,1000,"A"))));for(text in listOf("","invalid","1\n00:00:00,000 --> 00:00:11,000\nB",srt(listOf(VideoCaption(0,1000,"B"),VideoCaption(500,1500,"C"))),"\ud800","x".repeat(VideoCaptions.MAX_SRT_BYTES+1),"漢".repeat(60000))){assertThrows(Exception::class.java){VideoBilingualCaptions.prepare(c,0,10000,text)};assertEquals("A",c[0].captions.single().text)}}
 @Test fun noPrimaryInvalidIndexOrChangedSourceBoundsFail(){val secondary=srt(listOf(VideoCaption(0,1000,"B")));for(index in listOf(-1,1))assertThrows(IllegalArgumentException::class.java){VideoBilingualCaptions.prepare(listOf(clip(listOf(VideoCaption(0,1000,"A")))) ,index,10000,secondary)};assertThrows(IllegalArgumentException::class.java){VideoBilingualCaptions.prepare(listOf(clip(emptyList())),0,10000,secondary)};assertThrows(IllegalArgumentException::class.java){VideoBilingualCaptions.prepare(listOf(clip(listOf(VideoCaption(0,1000,"A")))),0,4999,secondary)}}
 @Test fun fullStoredSourceTrackRemainsIncludingOutsideTrimmedVisibility(){val c=clip(listOf(VideoCaption(0,1000,"Before trim"),VideoCaption(3000,4000,"Visible"))).copy(startMs=2000,endMs=4500);val r=VideoBilingualCaptions.prepare(listOf(c),0,10000,srt(listOf(VideoCaption(5000,6000,"After trim"))));assertEquals(listOf("Before trim","Visible","After trim"),r.clips[0].captions.map{it.text});assertEquals(2000L,r.clips[0].startMs);assertEquals(4500L,r.clips[0].endMs);assertEquals(c.captionSourceUri,r.clips[0].captionSourceUri)}
 @Test fun excessiveClipOrWholeProjectCueExpansionIsAtomic(){val a=listOf(VideoCaption(0,10000,"A"));val b=List(100){i->VideoCaption(i*100L+25,i*100L+75,"B$i")};assertThrows(IllegalArgumentException::class.java){merge(a,b)};val clips=List(1000){VideoSegment(0,2000,captions=listOf(VideoCaption(0,1000,"A")))};assertThrows(IllegalArgumentException::class.java){VideoBilingualCaptions.prepare(clips,0,2000,srt(listOf(VideoCaption(500,1500,"B"))))};assertEquals(1000,clips.sumOf{it.captions.size})}
 @Test fun decodedProjectUtf8TextGrowthLimitIsEnforced(){val a=List(100){i->VideoCaption(i*100L,i*100L+50,"x".repeat(100))};val b=List(100){i->VideoCaption(i*100L,i*100L+50,"漢".repeat(30))};val other=VideoSegment(0,10000,captions=List(100){i->VideoCaption(i*100L,i*100L+50,"漢".repeat(160))});val clips=listOf(VideoSegment(0,10000,captions=a),other);assertThrows(IllegalArgumentException::class.java){VideoBilingualCaptions.prepare(clips,0,10000,srt(b))};assertEquals(a,clips[0].captions)}
 @Test fun randomIndependentPerMillisecondReferencePreservesAllCoverageAndPlayback(){val rng=Random(132);repeat(40){val a=List(5){i->val from=i*300L+rng.nextLong(0,100);VideoCaption(from,from+rng.nextLong(50,200),"p$i")};val b=List(5){i->val from=i*300L+rng.nextLong(0,100);VideoCaption(from,from+rng.nextLong(50,200),"s$i")};val old=VideoSegment(0,2000,speed=listOf(.5f,1f,1.5f,2f)[rng.nextInt(4)],captions=a);val result=VideoBilingualCaptions.prepare(listOf(old),0,2000,srt(b));val merged=result.clips[0].captions;for(t in 0L until 2000L){val first=a.firstOrNull{t>=it.startMs&&t<it.endMs}?.text;val second=b.firstOrNull{t>=it.startMs&&t<it.endMs}?.text;val expected=listOfNotNull(first,second).joinToString("\n").ifEmpty{null};assertEquals(expected,merged.firstOrNull{t>=it.startMs&&t<it.endMs}?.text)};assertTrue(merged.zipWithNext().all{(x,y)->x.endMs<=y.startMs});assertEquals(old.durationUs,result.clips[0].durationUs);assertEquals(a,old.captions)}}
 @Test fun realProjectOneUndoRedoKeepsOtherEditsSoundtrackProvenanceAndCodec(){val old=clip(listOf(VideoCaption(0,1000,"First"))).copy(title="Keep",speed=1.5f,grade=VideoGrade(exposure=.5f),motion=VideoMotion(enabled=true,endZoom=1.5f,anchorEndMs=5000));val neighbor=VideoSegment(5000,9000);val p=VideoEditProject(10000);val music=VideoSoundtrack("content://synthetic/music",20000,loop=false);p.restore(listOf(old,neighbor),soundtrack=music);val r=VideoBilingualCaptions.prepare(p.segments,0,10000,srt(listOf(VideoCaption(500,1500,"Second"))),music);assertSame(neighbor,r.clips[1]);assertEquals(old.copy(captions=r.clips[0].captions),r.clips[0]);val request=VideoBatchReview(p.segments,music);val stage=Any();request.open(stage);request.propose(stage,r.clips);assertTrue(request.apply(stage,p){});assertEquals(music,p.soundtrack);assertEquals(old.captionSourceUri,p.segments[0].captionSourceUri);assertTrue(p.undo());assertEquals(listOf(old,neighbor),p.segments);assertFalse(p.canUndo);assertTrue(p.redo());val draft=VideoDraft(10000,p.segments,0,0,0,5000,soundtrack=music);assertEquals(draft,VideoDraftCodec.decode(VideoDraftCodec.encode(draft),10000));assertFalse(request.apply(stage,p){})}
 @Test fun dismissedForeignPausedAndChangedApprovalCannotMutateFirstTrack(){for(mode in 0..3){val old=clip(listOf(VideoCaption(0,1000,"A")));val p=VideoEditProject(10000);p.restore(listOf(old));val r=VideoBilingualCaptions.prepare(p.segments,0,10000,srt(listOf(VideoCaption(0,1000,"B"))));val request=VideoBatchReview(p.segments,null);val stage=Any();request.open(stage);request.propose(stage,r.clips);when(mode){0->{request.dismiss(stage);assertFalse(request.apply(stage,p){})};1->assertFalse(request.apply(Any(),p){});2->assertThrows(IllegalStateException::class.java){request.apply(stage,p){error("paused")}};3->{p.setTitle(0,"Changed");assertThrows(IllegalArgumentException::class.java){request.apply(stage,p){}}}};assertEquals(old.captions,p.segments[0].captions)}}
}
